import io.ktor.http.*
import java.security.MessageDigest
import java.text.Normalizer
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

data class ServiceIdentity(val name: String, val endpoint: String, val publicKeyHash: String)

object ServiceRegistry {
    private val trustedServices = mutableMapOf<String, ServiceIdentity>()

    init {
        trustedServices["model-trainer"] = ServiceIdentity(
            "model-trainer", "https://trainer.internal:8443", "a]b2c3d4e5f6"
        )
        trustedServices["data-pipeline"] = ServiceIdentity(
            "data-pipeline", "https://pipeline.internal:8443", "f6e5d4c3b2a1"
        )
        trustedServices["feature-store"] = ServiceIdentity(
            "feature-store", "https://features.internal:8443", "1a2b3c4d5e6f"
        )
    }

    fun isRegistered(serviceName: String): Boolean {
        return trustedServices.containsKey(serviceName)
    }

    fun getService(serviceName: String): ServiceIdentity? {
        return trustedServices[serviceName]
    }
}

object HomographDetector {
    private val CONFUSABLE_RANGES = listOf(
        0x0400..0x04FF,  // Cyrillic
        0x0370..0x03FF,  // Greek
        0x2000..0x206F,  // General Punctuation
        0xFF00..0xFFEF   // Halfwidth/Fullwidth Forms
    )

    fun containsHomoglyphs(input: String): Boolean {
        for (char in input) {
            for (range in CONFUSABLE_RANGES) {
                if (char.code in range) {
                    return true
                }
            }
        }
        return false
    }

    fun normalizeServiceName(name: String): String {
        // NFC normalization to canonical form
        val normalized = Normalizer.normalize(name, Normalizer.Form.NFC)
        return normalized
    }
}

object AuthTokenValidator {
    private val HMAC_SECRET: String = System.getenv("HMAC_SECRET")
        ?: throw IllegalStateException("HMAC_SECRET environment variable must be set; refusing to start with an insecure default secret")

    fun validateToken(token: String, serviceName: String, timestamp: Long): Boolean {
        val currentTime = System.currentTimeMillis() / 1000
        if (Math.abs(currentTime - timestamp) > 300) {
            return false
        }
        val expectedToken = generateToken(serviceName, timestamp)
        return MessageDigest.isEqual(token.toByteArray(), expectedToken.toByteArray())
    }

    fun generateToken(serviceName: String, timestamp: Long): String {
        val mac = Mac.getInstance("HmacSHA256")
        val keySpec = SecretKeySpec(HMAC_SECRET.toByteArray(), "HmacSHA256")
        mac.init(keySpec)
        val data = "$serviceName:$timestamp"
        return mac.doFinal(data.toByteArray()).joinToString("") { "%02x".format(it) }
    }
}

class InferenceRequestHandler {
    fun authenticateRequest(serviceName: String, token: String, timestamp: Long): Boolean {
        // Step 1: Check for obvious homoglyphs in the raw input
        if (HomographDetector.containsHomoglyphs(serviceName)) {
            println("[SECURITY] Homoglyph detected in service name: $serviceName")
            return false
        }

        // Step 2: Normalize the service name
        val normalizedName = HomographDetector.normalizeServiceName(serviceName)

        // Step 3: Verify service is registered
        if (!ServiceRegistry.isRegistered(normalizedName)) {
            println("[AUTH] Unknown service: $normalizedName")
            return false
        }

        // Step 4: Validate the HMAC token using the NORMALIZED service name
        // This ensures the token matches the canonical service identity
        return AuthTokenValidator.validateToken(token, normalizedName, timestamp)
    }

    fun runInference(modelId: String, inputData: FloatArray): FloatArray {
        // Simulated ML inference
        return FloatArray(10) { inputData.getOrElse(it) { 0.0f } * 0.5f }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/v1/inference") {
                val serviceName = call.request.header("X-Service-Name") ?: ""
                val authToken = call.request.header("X-Auth-Token") ?: ""
                val timestamp = call.request.header("X-Timestamp")?.toLongOrNull() ?: 0L

                val handler = InferenceRequestHandler()

                if (!handler.authenticateRequest(serviceName, authToken, timestamp)) {
                    call.respond(HttpStatusCode.Unauthorized, "Authentication failed")
                    return@post
                }

                val result = handler.runInference("default-model", floatArrayOf(1.0f, 2.0f, 3.0f))
                call.respond(HttpStatusCode.OK, result.joinToString(","))
            }
        }
    }.start(wait = true)
}
